window.RanchActions?.register('tileGame',{revision:()=>revision,read,unavailable:()=>!ready?'Assets loading':drag?'Finish or cancel the current drag':null,actions:{
 inspect:{readOnly:true,description:'Inspect tiles, recipes, resources and connections',schema:schema({}),run:read},
 place:{description:'Place a new sandbox prefab instance',schema:schema({kind:{type:'string',enum:cards.map(c=>c.id)},q:coord,r:coord,level,rotation}),run:a=>({instanceId:place(a.kind,a.q,a.r,a.level,a.rotation).id})},
 move:{description:'Move existing tile without resetting goods or progress',schema:schema({instanceId:{type:'string'},q:coord,r:coord,level,rotation}),run:a=>{const t=w.tiles.find(t=>t.id===a.instanceId);if(!t||!canPlace(w,a.q,a.r,a.level,t.id)||occupied(w,t.q,t.r,t.level+1))throw Error('Invalid move or tile supports another tile');const move=beginMove(w,t.id);commitMove(move,{q:a.q,r:a.r,level:a.level,rotation:a.rotation});return {instanceId:t.id};}},
 pause:{description:'Pause or resume recipe simulation',schema:schema({paused:{type:'boolean'}}),run:a=>setPaused(a.paused)},
 reducedMotion:{description:'Suppress spring and dust',schema:schema({enabled:{type:'boolean'}}),run:a=>setReduced(a.enabled)},
 recenter:{description:'Frame placed tiles',schema:schema({}),run:()=>{frameWorld();changed();}},
 exportWorld:{readOnly:true,description:'Export session world without writing Board storage',schema:schema({}),run:snapshot}
}});
setInterval(()=>window.RanchView?.changed(),5000);

window.tileGame.inspect=read;
